S = [('Übersicht', [('Vorlesung 5: *welche Kräfte* gibt es konkret?', 'Willkommen zu Vorlesung fünf. In Vorlesung vier haben wir gelernt, was Kräfte bewirken: F gleich m mal a. Jetzt schauen wir uns an, welche Kräfte es konkret gibt und wie man sie berechnet.'), ('Gravitation · Normalkraft · *Reibung* · Luftwiderstand · Kreis · *Seil*', 'Die Reihenfolge: Gravitation und Gewichtskraft, dann Normalkraft und Reibung, Luftwiderstand, die Kraft bei der Kreisbewegung und zum Schluss Seilkraft und Rolle.')]), ('Gravitation', [('*Gravitation*: alle Massen ziehen sich an – ohne Berührung', 'Gravitation bedeutet: Alle Körper mit Masse ziehen sich gegenseitig an, auch ohne sich zu berühren.'), ('Apfel und Mond: *dieselbe Kraft* – der Mond fliegt *seitlich* weiter', 'Die Erde zieht den Apfel und den Mond an. Der Apfel fällt einfach herunter. Der Mond fällt auch ständig auf die Erde zu, bewegt sich aber gleichzeitig so schnell seitlich, dass er immer an ihr vorbeifällt. So entsteht seine Kreisbahn.'), ('Gravitation ist *immer anziehend* und reicht *beliebig weit*', 'Gravitation zieht immer an, sie stößt nie ab. Und sie reicht beliebig weit, sie wird nur mit wachsendem Abstand schwächer.')]), ('Gravitationsgesetz', [('*F = G · m_1 · m_2 / r²*', 'Für zwei Kugeln gilt das Gravitationsgesetz: F gleich G mal m eins mal m zwei durch r Quadrat. r ist der Abstand der Mittelpunkte.'), ('*G ≈ 6,674 · 10⁻¹¹ N·m²/kg²* – winzig', 'G ist die Gravitationskonstante, rund sechs Komma sechs sieben vier mal zehn hoch minus elf. Das ist winzig. Deshalb merkt man Gravitation erst bei sehr großen Massen wie der Erde.')]), ('Masse und Abstand', [('Eine Masse *verdoppeln* → *2 F*', 'Was passiert, wenn man etwas ändert? Verdoppelt man eine der Massen, verdoppelt sich die Kraft. Sie steht ja einfach im Zähler.'), ('Abstand *verdoppeln* → *F / 4*', 'Verdoppelt man den Abstand, wird die Kraft viermal kleiner. Denn r steht im Nenner im Quadrat: zwei Quadrat ist vier.'), ('Newtons Test: Mond in *60 Erdradien* → *g / 3600 ≈ 0,0027 m/s²*', 'Damit hat Newton seine Idee geprüft: Der Mond ist etwa sechzig Erdradien entfernt. Die Anziehung muss dort also sechzig Quadrat, das sind dreitausendsechshundert Mal, kleiner sein. Neun Komma acht eins durch dreitausendsechshundert sind null Komma null null zwei sieben Meter pro Sekunde Quadrat. Und genau so groß ist die Zentripetalbeschleunigung, die der Mond für seine Bahn braucht.')]), ('Gewichtskraft', [('Nahe der Erde: *F_g = m · g* – senkrecht nach unten', 'Nahe der Erdoberfläche ist der Abstand zum Erdmittelpunkt praktisch immer gleich. Dann wird aus dem Gravitationsgesetz die einfache Formel F g gleich m mal g. Sie zeigt senkrecht nach unten.'), ('Doppelte Masse → *doppelte* Gewichtskraft · *g ≈ 9,81 m/s²*', 'Am selben Ort bedeutet doppelte Masse doppelte Gewichtskraft. g ist die Fallbeschleunigung, rund neun Komma acht eins Meter pro Sekunde Quadrat.')]), ('Zwei Kilogramm-Kugeln', [('Je *1 kg*, *1 m* Abstand: F = 6,7 · 10⁻¹¹ N', 'Warum spüren wir die Anziehung kleiner Körper nicht? Zwei Kugeln mit je einem Kilogramm im Abstand von einem Meter ziehen sich mit nur sechs Komma sieben mal zehn hoch minus elf Newton an.'), ('Gewichtskraft von 1 kg: *9,81 N* – rund *10¹¹-mal* größer', 'Die Gewichtskraft von einem Kilogramm ist dagegen neun Komma acht eins Newton. Das ist rund hundert Milliarden Mal mehr. Die Erde gewinnt, weil ihre Masse so riesig ist.')]), ('Normalkraft', [('Unterlage drückt *nach oben*: die *Normalkraft F_N*', 'Warum fällt ein Körper nicht durch den Tisch? Die Gewichtskraft zieht ihn nach unten, die Unterlage drückt ihn nach oben. Diese Kontaktkraft heißt Normalkraft.'), ('„Normal“ = *senkrecht zur Kontaktfläche*', 'Normal ist hier ein Fachwort aus der Mathematik und heißt senkrecht. Die Normalkraft steht immer senkrecht auf der Kontaktfläche.')]), ('Normalkraft und Waage', [('In Ruhe: *F_N − mg = 0 → F_N = mg*', 'Eine Waage misst eigentlich keine Masse, sondern eine Kraft. In Ruhe gleichen sich Gewichtskraft und Normalkraft aus. Also ist F N gleich m g.'), ('Anzeige: *m_Anzeige = F_N / g*', 'Die Waage rechnet die Kraft in eine Masse um: F N geteilt durch g. In Ruhe kommt genau die richtige Masse heraus.'), ('Zusatz Aufzug: 70 kg, a = 1 m/s² nach oben → Anzeige *77,2 kg*', 'Ein Zusatzbeispiel mit F gleich m a: Du stehst mit siebzig Kilogramm auf einer Waage im Aufzug, der mit einem Meter pro Sekunde Quadrat nach oben anfährt. Dann muss die Waage mehr drücken: F N gleich siebzig mal zehn Komma acht eins, also siebenhundertsiebenundfünfzig Newton. Die Waage zeigt siebenundsiebzig Komma zwei Kilogramm an.')]), ('Normalkraft auf der schiefen Fläche', [('F_N steht *senkrecht zur Fläche* – F_g zeigt *nach unten*', 'Auf einer geneigten Fläche steht die Normalkraft weiterhin senkrecht zur Fläche, also schräg. Die Gewichtskraft zeigt aber weiter senkrecht nach unten.'), ('F_g und F_N: *kein* Kraft-Gegenkraft-Paar – *selber Körper*', 'Ganz wichtig: Gewichtskraft und Normalkraft sind kein Kraft-Gegenkraft-Paar im Sinne von actio gleich reactio. Beide greifen an demselben Körper an. Hier sind sie nicht einmal gleich groß, denn die Normalkraft ist nur m g mal Kosinus Alpha.')]), ('Reibung beobachten', [('Langsam stärker ziehen: Kiste *bleibt erst stehen*', 'Jetzt die Reibung. Wir ziehen langsam immer stärker an einer Kiste. Zuerst bleibt sie stehen.'), ('*Haftreibung* gleicht die Zugkraft aus – bis zu einer *Grenze*', 'Solange sie steht, gleicht die Haftreibung die Zugkraft genau aus. Erst wenn eine Grenze überschritten wird, beginnt die Kiste zu gleiten.'), ('Animation: Holz auf Holz, F_N = 60 N → Grenze *30 N*, dann Gleiten mit *18 N*', 'Schau dir die Animation an: Holzkiste auf Holzboden mit sechzig Newton Normalkraft. Die Zugkraft wächst. Die Haftreibung wächst genau mit, bis zur Grenze von dreißig Newton. Dann rutscht die Kiste los, und die Reibung springt auf die kleinere Gleitreibung von achtzehn Newton. Weil die Zugkraft jetzt größer ist als die Reibung, wird die Kiste beschleunigt.')]), ('Haftreibung', [('Haftreibung *passt sich an* – höchstens *F_S,max = μ_S · F_N*', 'Die Haftreibung passt sich der Zugkraft an. Ihr Höchstwert ist proportional zur Normalkraft: F S max gleich mü S mal F N.'), ('*μ_S*: Haftreibungszahl, hängt vom *Oberflächenpaar* ab', 'Mü S ist die Haftreibungszahl. Sie hängt davon ab, welche Oberflächen sich berühren.'), ('Beispiel F_N = 60 N, μ_S = 0,5 → *F_S,max = 30 N*', 'Beispiel aus der Animation: Normalkraft sechzig Newton, Holz auf Holz mit mü S null Komma fünf. Die Kiste haftet also bis dreißig Newton Zugkraft. Ziehst du mit zwanzig Newton, ist die Haftreibung auch nur zwanzig Newton.')]), ('Gleitreibung', [('Gleitet die Kiste: *F_k = μ_k · F_N*', 'Gleitet die Kiste schon, wirkt die Gleitreibung F k gleich mü k mal F N. Sie zeigt gegen die Gleitrichtung.'), ('Zugkraft größer als F_k → Kiste wird *beschleunigt*', 'Ist die Zugkraft größer als die Gleitreibung, wird die Kiste weiter beschleunigt. Nach Newton zwei gilt dann: m a gleich F minus F k.'), ('Coulomb-Modell: F_k *unabhängig von v*', 'Im einfachen Coulomb-Modell ist die Gleitreibung unabhängig davon, wie schnell die Kiste rutscht.')]), ('Reibungszahlen', [('Gummi/Beton trocken: *μ_S = 1,0*, *μ_k = 0,7*', 'Hier typische Richtwerte. Gummi auf trockenem Beton: mü S eins, mü k null Komma sieben. Gleitreibung ist immer kleiner als Haftreibung.'), ('Nass: *0,5–0,7* bzw. *0,3–0,5* · Holz/Holz: *0,5* / *0,3*', 'Ist der Beton nass, sinken die Werte deutlich. Deshalb ist der Bremsweg auf nasser Straße länger. Holz auf Holz: null Komma fünf und null Komma drei.'), ('μ_S beschreibt die *Grenze*, nicht den gerade wirkenden Betrag', 'Und noch einmal der Merksatz: Mü S beschreibt die Grenze der Haftreibung, nicht den Wert, der gerade wirkt.')]), ('Reibung beim Gehen', [('Fuß drückt Boden *nach hinten* → Boden drückt Fuß *nach vorn*', 'Ohne Reibung könnten wir nicht laufen. Der Fuß drückt den Boden nach hinten. Nach actio gleich reactio drückt der Boden den Fuß nach vorn.'), ('Diese Kraft ist *Haftreibung* – der Fuß rutscht nicht', 'Diese Kraft nach vorn ist Haftreibung, denn der Fuß rutscht an der Kontaktstelle nicht. Auf Glatteis fehlt sie, dann rutscht man weg.')]), ('Gewichtskraft am Hang', [('Zerlegen: *Hangabtrieb F_H = mg sin α*', 'Am Hang zerlegt man die Gewichtskraft in zwei Teile. Der Teil entlang der Ebene heißt Hangabtriebskraft: m g mal Sinus Alpha.'), ('Senkrecht zur Ebene: *F_⊥ = mg cos α* (= F_N)', 'Der Teil senkrecht zur Ebene ist m g mal Kosinus Alpha. Genau diesen Teil gleicht die Normalkraft aus.'), ('Beispiel 10 kg, α = 30°: *F_H = 49,1 N*, *F_⊥ = 85,0 N*', 'Ein Beispiel: zehn Kilogramm bei dreißig Grad. m g sind achtundneunzig Komma eins Newton. Mal Sinus dreißig Grad, also mal null Komma fünf: neunundvierzig Komma eins Newton Hangabtrieb. Mal Kosinus dreißig Grad, null Komma acht sechs sechs: fünfundachtzig Newton senkrecht. Probe mit Pythagoras: Die Wurzel aus der Summe der Quadrate ergibt wieder achtundneunzig Komma eins.')]), ('Reibung auf der schiefen Ebene', [('*Haftgrenze*: Winkel langsam erhöhen → Klotz steht *gerade noch* → α_S', 'Mit der schiefen Ebene kann man Reibungszahlen messen. Erster Versuch: Man kippt die Ebene langsam immer steiler. Der Winkel, bei dem der Klotz gerade noch steht, heißt Alpha S.'), ('*Gleichförmiges Gleiten*: v konstant → α_k', 'Zweiter Versuch: Man sucht den Winkel, bei dem der Klotz mit konstanter Geschwindigkeit rutscht. Das ist Alpha k. Er ist kleiner als Alpha S.')]), ('Reibungszahl aus dem Winkel', [('Krafteck: *F_R / F_N = mg sin α / mg cos α = tan α*', 'Warum genügt der Winkel? Bei beiden Versuchen ist der Klotz im Gleichgewicht. Dann ist die Reibung gleich dem Hangabtrieb m g Sinus Alpha und die Normalkraft gleich m g Kosinus Alpha. Ihr Verhältnis ist Tangens Alpha. Die Masse kürzt sich heraus.'), ('*μ_S = tan α_S* · *μ_k = tan α_k*', 'Also gilt: mü S gleich Tangens Alpha S und mü k gleich Tangens Alpha k.'), ('Beispiel: α_S = 26,6° → μ_S = *0,50* · α_k = 16,7° → μ_k = *0,30*', 'Ein Beispiel: Rutscht ein Holzklotz bei sechsundzwanzig Komma sechs Grad los, ist mü S gleich Tangens davon, also null Komma fünf. Gleitet er bei sechzehn Komma sieben Grad gleichmäßig, ist mü k null Komma drei. Das passt genau zur Tabelle für Holz auf Holz.')]), ('Fall mit Luftwiderstand: Start', [('Start aus Ruhe: *F_W = 0* → *a = g*', 'Jetzt der Luftwiderstand. Ein Körper wird aus der Ruhe losgelassen. Im ersten Moment ist er noch nicht schnell, also gibt es noch keinen Luftwiderstand. Er fällt zuerst genau mit g.'), ('Nach unten positiv · *Auftrieb vernachlässigt*', 'Dabei zählen wir nach unten positiv und vernachlässigen den Auftrieb in der Luft.')]), ('Beschleunigung nimmt ab', [('Schneller → *mehr Luftwiderstand* → *F_res = mg − F_W* wird kleiner', 'Mit wachsender Geschwindigkeit wächst der Luftwiderstand. Die verbleibende Kraft nach unten, m g minus F W, wird kleiner, also auch die Beschleunigung.'), ('Aber: Er wird *trotzdem noch schneller* (0 < a < g)', 'Aber Achtung: Er wird trotzdem noch schneller. Die Beschleunigung ist kleiner als g, aber noch größer als null.')]), ('Luftwiderstand', [('*F_W = k_W · v²* mit *k_W = ½ c_W ρ A*', 'Der Luftwiderstand ist proportional zum Quadrat der Geschwindigkeit: F W gleich k W mal v Quadrat. Die Konstante k W ist ein halb mal c W mal rho mal A.'), ('c_W Form · ρ Luftdichte *1,2 kg/m³* · A Stirnfläche', 'c W beschreibt die Form, rho ist die Luftdichte, etwa eins Komma zwei Kilogramm pro Kubikmeter, und A ist die Stirnfläche, also die Fläche, die man von vorn sieht.'), ('*Doppelte v → vierfacher* Widerstand', 'Wichtigste Folge: Doppelte Geschwindigkeit heißt vierfacher Luftwiderstand. Das kennst du vom Spritverbrauch auf der Autobahn aus Blatt fünf.')]), ('Endgeschwindigkeit', [('Grenzfall: *F_W = F_g* → *a = 0*', 'Irgendwann ist der Luftwiderstand so groß wie die Gewichtskraft. Dann ist die resultierende Kraft null und damit auch die Beschleunigung.'), ('v wächst nicht weiter – der Körper *fällt aber weiter*', 'Die Geschwindigkeit wächst dann nicht mehr. Der Körper bleibt aber nicht stehen, er fällt mit dieser konstanten Endgeschwindigkeit weiter.')]), ('Endgeschwindigkeit berechnen', [('*k_W v∞² = mg → v∞ = √(mg / k_W)*', 'Aus F W gleich m g folgt: k W mal v unendlich Quadrat gleich m g. Nach v aufgelöst: Wurzel aus m g durch k W.'), ('100 kg, k_W = 0,6 kg/m → *v∞ = √1635 ≈ 40,4 m/s*', 'Mit hundert Kilogramm und k W null Komma sechs: hundert mal neun Komma acht eins durch null Komma sechs sind sechzehnhundertfünfunddreißig. Die Wurzel daraus ist vierzig Komma vier Meter pro Sekunde, also etwa hundertfünfundvierzig Kilometer pro Stunde.'), ('Tabelle: nach 15 s *147,2* ohne – *40,4 m/s* mit Luftwiderstand', 'Die Tabelle vergleicht: Ohne Luft wäre der Körper nach fünf Sekunden schon neunundvierzig Meter pro Sekunde schnell, mit Luft nur vierunddreißig. Nach fünfzehn Sekunden: hundertsiebenundvierzig gegen vierzig Komma vier. Die Endgeschwindigkeit ist praktisch erreicht.')]), ('v, a und s beim Fall', [('v(t): steigt schnell, nähert sich *40,4 m/s*', 'Die drei Diagramme zeigen den Fall mit Luftwiderstand über sechzehn Sekunden. Links die Geschwindigkeit: Sie steigt am Anfang fast so schnell wie im freien Fall und nähert sich dann vierzig Komma vier Meter pro Sekunde.'), ('a(t): startet bei *g = 9,81* und geht gegen *0*', 'In der Mitte die Beschleunigung: Sie beginnt bei neun Komma acht eins und geht gegen null. Das ist die Steigung der linken Kurve.'), ('s(t): später fast eine *Gerade* – v ist konstant', 'Rechts der Weg: Am Anfang eine Parabel wie beim freien Fall, später fast eine Gerade. Eine Gerade im Weg-Zeit-Diagramm heißt konstante Geschwindigkeit. Nach fünfzehn Sekunden ist der Körper etwa fünfhundert Meter gefallen.'), ('Merke: *v → 40,4 m/s*, *a → 0*, s wächst *gleichmäßig*', 'Genau das steht unten auf der Folie: v nähert sich vierzig Komma vier, a nähert sich null, und der Weg wächst später gleichmäßig.')]), ('Kreisbewegung braucht eine Kraft', [('Betrag von v gleich, *Richtung ändert sich* → Kraft nötig', 'Auch eine gleichförmige Kreisbewegung braucht eine Kraft. Der Betrag der Geschwindigkeit bleibt zwar gleich, aber ihre Richtung ändert sich ständig. Und jede Änderung der Geschwindigkeit braucht nach Newton eine Kraft.'), ('Kraft *nach innen*: Zentripetalkraft · hier liefert sie das *Seil*', 'Diese Kraft zeigt nach innen und heißt Zentripetalkraft. Im Bild liefert sie das Seil, an dem die Kugel kreist. Rot: die Geschwindigkeit, grün: die Kraft zum Mittelpunkt.')]), ('Zentripetalkraft', [('*F_Z = m v² / r*', 'Wie groß muss diese Kraft sein? F Z gleich m mal v Quadrat durch r. Das folgt aus F gleich m a mit der Zentripetalbeschleunigung v Quadrat durch r aus Vorlesung drei.'), ('~ m · *doppelte v → vierfache Kraft* · ~ 1/r', 'Daraus liest man ab: Die Kraft ist proportional zur Masse. Doppelte Geschwindigkeit braucht die vierfache Kraft. Und bei gleicher Geschwindigkeit braucht ein kleinerer Radius mehr Kraft. Deshalb sind enge Kurven bei hohem Tempo gefährlich.')]), ('Beispiel: Seilkraft', [('m = 0,20 kg, v = 2,0 m/s, r = 0,50 m', 'Ein Beispiel: Kugel mit zweihundert Gramm, zwei Meter pro Sekunde, Radius fünfzig Zentimeter.'), ('F_Z = 0,20 · 2,0² / 0,50 = *1,6 N*', 'Eingesetzt: null Komma zwei mal vier durch null Komma fünf, das sind eins Komma sechs Newton. Genau diese Kraft muss das Seil liefern.'), ('Seil reißt → Kugel fliegt *tangential geradeaus* weiter', 'Und was passiert, wenn das Seil reißt? Dann fehlt die Kraft nach innen. Nach dem Trägheitsprinzip fliegt die Kugel geradeaus weiter, und zwar tangential, also in die Richtung, in die sie gerade fliegt. Nicht nach außen!')]), ('Seilkraft', [('Seil überträgt *nur Zug* – entlang des Seils', 'Ein straffes Seil überträgt nur Zugkräfte, und zwar entlang des Seils. Drücken kann man mit einem Seil nicht.'), ('Hand zieht am Seil, Seil zieht *gleich stark* an der Hand', 'Die Hand zieht am Seil, das Seil zieht genauso stark an der Hand. Das ist wieder actio gleich reactio: Die beiden Kräfte greifen an verschiedenen Körpern an.')]), ('Ideales Seil', [('Seilmasse vernachlässigt → *F_1 = F_2* überall gleich', 'Beim idealen Seil vernachlässigen wir die Masse. Dann ist die Zugkraft überall im Seil gleich groß: F eins gleich F zwei.'), ('Warum? Masseloses Stück: *m·a = F_2 − F_1 = 0*', 'Warum? Nimm ein Stück Seil heraus. Es hat keine Masse, also ist m mal a gleich null. Dann müssen die Kräfte an beiden Enden gleich groß sein, egal wie das Seil beschleunigt.')]), ('Feste Rolle', [('Feste Rolle *lenkt nur um* – Seilkraft bleibt gleich', 'Eine feste Rolle lenkt die Zugrichtung um. Ist sie masselos und reibungsfrei, ist die Seilkraft auf beiden Seiten gleich groß.'), ('*Spart keine Kraft*: Last m·g → Zug m·g', 'Eine feste Rolle allein spart also keine Kraft. Um einen Eimer mit hundert Newton Gewicht gleichmäßig hochzuziehen, brauchst du auch hundert Newton. Bequemer ist nur die Richtung: Du ziehst nach unten. Kraft sparen erst lose Rollen, wie in Blatt fünf.')]), ('Bewegung an der festen Rolle', [('Seillänge konstant: *Δl_1 = −Δl_2*', 'Weil das Seil straff bleibt und seine Länge gleich bleibt, gilt: Geht ein Ende nach unten, geht das andere um genau denselben Betrag nach oben.'), ('Auch *v* und *a* an beiden Enden gleich groß', 'Daraus folgt durch Ableiten: Auch Geschwindigkeit und Beschleunigung sind an beiden Enden gleich groß. Das brauchst du für jede Aufgabe mit zwei Massen an einer Rolle.')]), ('Kraftgesetze im Überblick', [('*Gesetze*: Gravitation, Gewicht, Reibung, Luft, Zentripetal', 'Hier alles auf einen Blick. Für Gravitation, Gewichtskraft, Haft- und Gleitreibung, Luftwiderstand und Zentripetalkraft gibt es eine Formel.'), ('Normalkraft und Seilkraft: *aus der Kräftebilanz*', 'Normalkraft und Seilkraft haben keine eigene Formel. Man berechnet sie immer aus der Kräftebilanz am Körper, also mit Newton zwei.'), ('Zentripetalkraft ist *keine eigene Kraftart*: m v²/r ist, was *nötig* ist', 'Achte auf das Wort nötig bei der Zentripetalkraft. Sie ist keine eigene Kraftart, sondern die Kraft, die für die Kreisbahn nötig ist. Geliefert wird sie von einer echten Kraft, zum Beispiel vom Seil, der Reibung oder der Gravitation.')]), ('Verständnisfragen', [('Vier Fragen – *überleg kurz selbst*', 'Zum Schluss vier Verständnisfragen. Halte kurz an und überlege selbst, bevor wir die Lösung anschauen.')]), ('Auflösung', [('1. *Nein* – beide greifen am *selben Körper* an', 'Erstens: Nein. Gewichtskraft und Normalkraft greifen am selben Körper an. Ein Kraft-Gegenkraft-Paar wirkt immer auf zwei verschiedene Körper.'), ('2. *100 N* – nicht μ_S · F_N', 'Zweitens: hundert Newton. Die Haftreibung ist genau so groß wie die Zugkraft, solange ihre Grenze reicht.'), ('3. *Nein* – er fällt mit *konstanter v* weiter', 'Drittens: Nein. Mit Endgeschwindigkeit fällt der Körper mit konstanter Geschwindigkeit weiter.'), ('4. *Tangential* geradeaus – *nicht* nach außen', 'Viertens: Die Kugel fliegt tangential geradeaus weiter, nicht nach außen. Damit ist Vorlesung fünf geschafft.')])]
